            session.rollback();
            throw new BusinessConflictException("Case cannot be submitted");
        }

        audit.insertStatusHistory(
            command.tenantId(),
            command.caseId(),
            "DRAFT",
            "SUBMITTED",
            "SUBMIT",
            command.actorId()
        );

        outbox.insertCaseSubmitted(
            command.tenantId(),
            command.caseId(),
            updated.version(),
            command.correlationId()
        );

        session.commit();

        return new SubmitCaseResult(
            updated.tenantId(),
            updated.caseId(),
            updated.status(),
            updated.version()
        );
    }
}
