        className: "language-sql",
        children: "CREATE OR REPLACE FUNCTION submit_case(
    p_tenant_id bigint,
    p_case_id uuid,
    p_actor_id text,
    p_expected_version bigint
)
RETURNS TABLE (
    tenant_id bigint,
    case_id uuid,
    status text,
    version bigint,
    submitted_at timestamptz
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_status text := 'DRAFT';
BEGIN
    RETURN QUERY
    WITH updated AS (
        UPDATE regulatory_case c
        SET status = 'SUBMITTED',
            submitted_at = clock_timestamp(),
            version = c.version + 1,
            updated_by = p_actor_id,
            updated_at = clock_timestamp()
        WHERE c.tenant_id = p_tenant_id
          AND c.case_id = p_case_id
          AND c.status = v_from_status
          AND c.version = p_expected_version
          AND c.deleted_at IS NULL
        RETURNING
            c.tenant_id,
            c.case_id,
            c.status,
            c.version,
            c.submitted_at
    ),
    inserted_history AS (
        INSERT INTO case_status_history (
            tenant_id,
            case_id,
            from_status,
            to_status,
            action,
            changed_by
        )
        SELECT
            u.tenant_id,
            u.case_id,
            v_from_status,
            u.status,
            'SUBMIT',
            p_actor_id
        FROM updated u
        RETURNING tenant_id, case_id
    )
    SELECT
        u.tenant_id,
        u.case_id,
        u.status,
        u.version,
        u.submitted_at
    FROM updated u;
END;
