            u.tenant_id,
            u.case_id,
            'DRAFT',
            u.status,
            'SUBMIT',
            p_actor_id
        FROM updated u
        RETURNING tenant_id, case_id
    )
    SELECT
        u.tenant_id,
        u.case_id,
        u.status,
        u.version
    FROM updated u;
END;
