                command.tenantId(),
                command.title(),
                command.actorId()
            );

            outbox.insert(
                command.tenantId(),
                inserted.caseId(),
                "CASE_CREATED",
                buildCaseCreatedPayload(inserted)
            );

            CreateCaseResult result = new CreateCaseResult(
                inserted.tenantId(),
                inserted.caseId(),
                inserted.caseNumber(),
                inserted.version()
            );

            idem.complete(
                command.tenantId(),
                command.idempotencyKey(),
                "CREATE_CASE",
                command.requestHash(),
                201,
                encodeJson(result)
            );

            session.commit();
            return result;
        }
